# calls (outside the repo): substring, push, some, join
function formatBotComment({
  author,
  baseRef,
  baseSha,
  headRef,
  headSha,
  behindBy,
  aheadBy,
  status,
  mergeable,
  mergeableState,
  linkedIssues,
  linesChanged,
  changedFiles,
  guidance,
  labelsApplied,
  retargetedToDevelop = false,
  ai = null,
  checks = null,
  aiSkipReason = '',
  reviewer = '',
  ledger = null,
}) {
  baseRef = escapeMdRef(baseRef);
  headRef = escapeMdRef(headRef);
  const shortBaseSha = baseSha ? baseSha.substring(0, 7) : 'unknown';
  const shortHeadSha = headSha ? headSha.substring(0, 7) : 'unknown';

  let alertBlock = '';
  const warnings = [];

