# doc: The bare hostname of a `Host` header, with `:port` and `[...]` stripped.      Returns None for anything empty or unparseable -- fail closed rather than     guess.
def _hostname_from_host_header(value: str | None) -> str | None:
    """The bare hostname of a `Host` header, with `:port` and `[...]` stripped.

    Returns None for anything empty or unparseable -- fail closed rather than
    guess.
    """
    if not value:
        return None
    value = value.strip()
    if not value:
        return None
    if value.startswith("["):
        end = value.find("]")
        if end == -1:
            return None
        return value[1:end].lower() or None
    head, sep, tail = value.rpartition(":")
    if sep and tail.isdigit():
        return head.lower() or None
    return value.lower()

