# called by: scripts/bump_version.py::main
# calls: scripts/bump_version.py::parse_semver
# calls (outside the repo): strip, lower, lstrip
def compute_next_version(current: str, bump_type: str) -> str:
    major, minor, patch = parse_semver(current)
    b = bump_type.lower().strip()
    if b == "patch":
        return f"{major}.{minor}.{patch + 1}"
    elif b == "minor":
        return f"{major}.{minor + 1}.0"
    elif b == "major":
        return f"{major + 1}.0.0"
    else:
        # User specified an explicit version string
        parse_semver(b)  # validate
        return b.lstrip("v")

