# doc: A response double that serves sized reads the way urlopen's does.      `served` counts every byte handed out through *either* access path -- the     sized `read(n)` the fix uses and the line iteration the old code used -- so     an assertion on it measures what left the socket, not what the caller  
class SizedResponse:
    """A response double that serves sized reads the way urlopen's does.

    `served` counts every byte handed out through *either* access path -- the
    sized `read(n)` the fix uses and the line iteration the old code used -- so
    an assertion on it measures what left the socket, not what the caller
    happened to keep.
    """

    def __init__(self, body: bytes):
        self._buf = io.BytesIO(body)
        self.served = 0
        self.status = 200
        self.headers = {"Content-Type": "text/event-stream"}

    def read(self, size=-1):
        block = self._buf.read(size)
        self.served += len(block)
        return block

    def __iter__(self):
        for line in self._buf:
            self.served += len(line)
            yield line

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        return False

    def close(self):
        pass

